      display: inline-block !important;
      white-space: nowrap !important;
      padding-left: 100% !important; /* Điểm bắt đầu từ ngoài mép phải màn hình */
      animation: customMarqueeFull 22s linear infinite !important;
      will-change: transform;
    }

    /* Rê chuột vào sẽ tạm dừng để dễ đọc */
    #information_div .marquee-text:hover {
      animation-play-state: paused !important;
    }

    @keyframes customMarqueeFull {
      0% {
        transform: translateX(0);
      }
      100% {
        transform: translateX(-100%); /* Trượt xuyên suốt sang mép trái */
