  if (typeof GM_addStyle !== 'undefined') {
    GM_addStyle(marqueeFixCSS);
  } else {
    const styleEl = document.createElement('style');
    styleEl.textContent = marqueeFixCSS;
    document.head.appendChild(styleEl);
  }

  // 2. Logic can thiệp giao diện Header & Thông báo
  function processHeader() {
    // A. Kiểm tra bác sĩ đăng nhập (Phan Đình Huy / BSCKI.Phan Đình Huy)
    const doctorNameEl = document.querySelector('#table_header .bs-doctor-name');
    const logoutBtn = document.querySelector('#table_header a.logout');

    if (doctorNameEl && logoutBtn && !logoutBtn.dataset.goodbyeAttached) {
      const doctorText = doctorNameEl.textContent.trim().toLowerCase();
      const targetName = 'phan đình huy';

      if (doctorText.includes(targetName)) {
        logoutBtn.dataset.goodbyeAttached = 'true';

        logoutBtn.addEventListener('mouseenter', () => {
          logoutBtn.textContent = 'GOOD BYE!';
        });

        logoutBtn.addEventListener('mouseleave', () => {
          logoutBtn.textContent = 'Đăng xuất';
        });
      }
    }

    // B. Thay thế toàn bộ "Thông báo: ; ;" thành thông điệp ý nghĩa
    const marqueeTextEl = document.querySelector('#information_div .marquee-text');
    if (marqueeTextEl) {
      const targetText = 'CẤP CỨU CHUYÊN NGHIỆP - BẮT KỊP SỰ SỐNG! Chăm sóc sức khỏe cho mọi người là nghề cao quý!';

      // Nếu thẻ đã bị thay đổi trước đó rồi thì bỏ qua để tránh lặp vô tận
      if (!marqueeTextEl.dataset.customNotice) {
        // Kiểm tra xem có chứa chữ Thông báo hoặc dấu chấm phẩy
        if (marqueeTextEl.textContent.includes('Thông báo') || marqueeTextEl.textContent.includes(';')) {
          // Thay thế toàn bộ nội dung hiển thị trong .marquee-text
          marqueeTextEl.innerHTML = `<span style="font-weight: 500; color: #0056b3;">${targetText}</span>`;
          marqueeTextEl.dataset.customNotice = 'true';
        }
      }
    }
  }

  // Khởi chạy khi DOM sẵn sàng
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', processHeader);
  } else {
    processHeader();
  }

  // Lắng nghe MutationObserver phòng khi HIS nạp trễ qua AJAX
  const observer = new MutationObserver(() => {
    processHeader();
  });

  observer.observe(document.body, {
    childList: true,
    subtree: true
  });
})();

