    // ==========================================
    // CÁC HÀM TIỆN ÍCH
    // ==========================================

    function isElementVisible(el) {
        if (!el) return false;
        const hasShowClass = el.classList.contains('show');
        const isDisplayBlock = window.getComputedStyle(el).display !== 'none';
        return hasShowClass || el.offsetParent !== null || isDisplayBlock;
    }

    function getFirstAvailableValue(selectors) {
        for (const selector of selectors) {
            const el = document.querySelector(selector);
            const val = el ? (el.value || el.textContent || '').trim() : '';
            if (val) return val;
        }
        return '';
    }

    function setFieldValue(selectorOrEl, val) {
        if (val === undefined || val === null) return;
        const el = typeof selectorOrEl === 'string' ? document.querySelector(selectorOrEl) : selectorOrEl;
        if (!el) return;

        el.value = val;
        el.dispatchEvent(new Event('input', { bubbles: true }));
        el.dispatchEvent(new Event('change', { bubbles: true }));

        if (window.jQuery) {
            const $el = window.jQuery(el);$el.trigger('input').trigger('change');
            if ($el.data('select2')) {$el.val(val).trigger('change');
            }
        }
    }

    // ==========================================
    // MODULE 1: BÁC SĨ HSBA
    // ==========================================
    function handleDoctorSelection() {
        const currentUser = document.querySelector('a.mau');
        if (currentUser?.textContent.trim() !== CONFIG.doctor.userName) return;

        const modal = document.querySelector(CONFIG.doctor.modalSelector);
        if (!isElementVisible(modal)) {
            if (modal?.dataset.doctorAutoFilled) {
                delete modal.dataset.doctorAutoFilled;
            }
            return;
        }

        if (modal.dataset.doctorAutoFilled === 'true') return;

        const doctorSelect = document.querySelector(CONFIG.doctor.selectSelector);
        if (!doctorSelect) return;

        setFieldValue(doctorSelect, CONFIG.doctor.targetValue);
        modal.dataset.doctorAutoFilled = 'true';
    }

    // ==========================================
    // MODULE 2: DINH DƯỠNG TRÊN 18
    // ==========================================
    function handleNutritionForm() {
        const modal = document.querySelector(CONFIG.nutrition.modalSelector);
        if (!isElementVisible(modal)) {
            if (modal?.dataset.nutritionAutoFilled) {
                delete modal.dataset.nutritionAutoFilled;
            }
            return;
        }

        if (modal.dataset.nutritionAutoFilled === 'true') return;

        const form = modal.querySelector(CONFIG.nutrition.formSelector) || document.querySelector(CONFIG.nutrition.formSelector);
        if (!form) return;

        const defaultEntries = Object.entries(CONFIG.nutrition.defaults);
        const isDomReady = defaultEntries.some(([id]) => form.querySelector(`#${id}`) !== null);
        if (!isDomReady) return;

        defaultEntries.forEach(([id, val]) => {
            const selectEl = form.querySelector(`#${id}`);
            if (selectEl) setFieldValue(selectEl, val);
        });

        Object.entries(CONFIG.nutrition.priorityInputs).forEach(([targetId, sourceSelectors]) => {
            const targetInput = form.querySelector(`#${targetId}`);
            if (targetInput) {
                const matchedValue = getFirstAvailableValue(sourceSelectors);
                if (matchedValue) setFieldValue(targetInput, matchedValue);
            }
        });

        modal.dataset.nutritionAutoFilled = 'true';
    }

    // ==========================================
    // MODULE 3: TRÍCH XUẤT CLIPBOARD
    // ==========================================
    async function getClipboardText() {
        if (navigator.clipboard && navigator.clipboard.readText) {
            try {
                return await navigator.clipboard.readText();
            } catch (e) {
                console.warn('[AutoFill] Clipboard error:', e);
            }
        }
        return '';
    }

    async function processClipboardData(targetElement) {
        const text = await getClipboardText();
        if (!text) return;

        const upperText = text.toUpperCase();

        const getValue = (startKey, endKey, cleanNewlines = true) => {
            const startIdx = upperText.indexOf(startKey.toUpperCase());
            if (startIdx === -1) return '';
            const contentStart = startIdx + startKey.length;
            const endIdx = upperText.indexOf(endKey.toUpperCase(), contentStart);
            if (endIdx === -1) return '';
            let result = text.substring(contentStart, endIdx).trim();
            return cleanNewlines ? result.replace(/\r?\n|\r/g, ' ') : result;
        };

        const benhSuVal = getValue("BỆNH SỬ:", "TIỀN SỬ:");
        const tienSuVal = getValue("TIỀN SỬ:", "KHÁM");
        const khamVal = getValue("KHÁM", "Tim");

        if (benhSuVal) setFieldValue(targetElement, benhSuVal);
        if (tienSuVal) setFieldValue(CONFIG.clipboard.selectors.tienSu, tienSuVal);
        if (khamVal) setFieldValue(CONFIG.clipboard.selectors.khamToanThan, khamVal);

        const machVal = getValue("M", "lần/phút").replace(/\s/g, '');
        if (machVal) setFieldValue(CONFIG.clipboard.selectors.mach, machVal);

        const haRaw = getValue("HA:", "mmHg").replace(/\s/g, '');
        if (haRaw) {
            const haParts = haRaw.split('/');
            if (haParts[0]) setFieldValue(CONFIG.clipboard.selectors.haTren, haParts[0]);
            if (haParts[1]) setFieldValue(CONFIG.clipboard.selectors.haDuoi, haParts[1]);
        }

        const originalBorder = targetElement.style.border;
        targetElement.style.border = '2px solid #28a745';
        setTimeout(() => { targetElement.style.border = originalBorder; }, 1200);
    }

    document.addEventListener('click', function (e) {
        const target = e.target.closest(CONFIG.clipboard.targetSelector);
        if (target) {
            processClipboardData(target);
        }
    }, true);

    // ==========================================
    // MODULE 4: CAM KẾT PT/GMHS (DELAY 1S & RETRY)
    // ==========================================

    const selectChoiceByText = async (modal, name, searchText) => {
        const select = modal.querySelector(`select[name="data[${name}]"], select[id$="-${name}"]`);
        if (!select) return false;

        const container = select.closest('.choices') || select.parentElement;
        if (!container) return false;

        container.scrollIntoView({ block: 'nearest' });

        // 1. Click mở dropdown
        container.click();
        await new Promise(r => setTimeout(r, 400));

        // 2. Tìm danh sách option đang hiển thị (class 'is-active')
        const activeDropdowns = modal.querySelectorAll('.choices__list--dropdown.is-active');
        let targetItem = null;

        activeDropdowns.forEach(dropdown => {
            const items = dropdown.querySelectorAll('.choices__item--choice');
            items.forEach(item => {
                if (item.textContent.trim().includes(searchText)) {
                    targetItem = item;
                }
            });
        });

        if (targetItem) {
            // 3. Chuỗi sự kiện chuột hoàn chỉnh
            const events = ['mousedown', 'mouseup', 'click'];
            events.forEach(ev => {
                targetItem.dispatchEvent(new MouseEvent(ev, {
                    bubbles: true,
                    cancelable: true,
                    view: window
                }));
            });
            await new Promise(r => setTimeout(r, 150));
            return true;
        } else {
            // Đóng menu nếu không tìm thấy để tránh kẹt giao diện
            container.click();
            return false;
        }
    };

    async function setChoicesMultipleOrSingle(modal, fieldName, values, textList, isMultiple = false) {
        const select = modal.querySelector(`select[name="data[${fieldName}]"], select[id$="-${fieldName}"]`);
        if (!select) return;

        let allSuccess = true;
        for (const text of textList) {
            const ok = await selectChoiceByText(modal, fieldName, text);
            if (!ok) allSuccess = false;
        }

        if (!allSuccess) {
            const container = select.closest('.choices') || select.parentElement;
            const choicesInstance = select.choices || container?.choices || select._choices;

            Array.from(select.options).forEach(opt => {
                if (values.includes(opt.value)) opt.selected = true;
            });
            if (!isMultiple && values[0]) select.value = values[0];

            if (choicesInstance && typeof choicesInstance.setChoiceByValue === 'function') {
                try {
                    if (isMultiple) {
                        choicesInstance.setChoiceByValue(values);
                    } else {
                        choicesInstance.setChoiceByValue(values[0]);
                    }
                } catch (e) {}
            }

            select.dispatchEvent(new Event('input', { bubbles: true }));
            select.dispatchEvent(new Event('change', { bubbles: true }));
        }
    }

    function applyCurrentDateToFlatpickr(modal) {
        const hiddenInput = modal.querySelector('input[name="data[NGAY_TAO_PHIEU]"], input[id$="-NGAY_TAO_PHIEU"]');
        if (!hiddenInput) return;

        const inputGroup = hiddenInput.closest('.input-group') || hiddenInput.parentElement;
        const visibleInput = inputGroup ? inputGroup.querySelector('input.form-control.input, input[type="text"]:not([type="hidden"])') : null;

        const fp = hiddenInput._flatpickr || visibleInput?._flatpickr || inputGroup?._flatpickr;

        const now = new Date();
        const pad = n => String(n).padStart(2, '0');
        const d = pad(now.getDate());
        const m = pad(now.getMonth() + 1);
        const y = now.getFullYear();
        const hr = pad(now.getHours());
        const mi = pad(now.getMinutes());
        const sc = pad(now.getSeconds());

        const isoVal = `${y}-${m}-${d} ${hr}:${mi}:${sc}`;
        const displayVal = `${d}/${m}/${y} ${hr}:${mi}`;

        if (fp && typeof fp.setDate === 'function') {
            fp.setDate(now, true);
        }

        hiddenInput.value = isoVal;
        hiddenInput.dispatchEvent(new Event('input', { bubbles: true }));
        hiddenInput.dispatchEvent(new Event('change', { bubbles: true }));

        if (visibleInput) {
            visibleInput.value = displayVal;
            visibleInput.dispatchEvent(new Event('input', { bubbles: true }));
            visibleInput.dispatchEvent(new Event('change', { bubbles: true }));
        }

        if (window.jQuery) {
            window.jQuery(hiddenInput).trigger('change');
            if (visibleInput) window.jQuery(visibleInput).trigger('change');
        }
    }

    async function handleProcedureConsentForm() {
        const modal = document.querySelector(CONFIG.procedure.modalSelector);
        if (!isElementVisible(modal)) {
            if (modal?.dataset.procedureAutoFilled) {
                delete modal.dataset.procedureAutoFilled;
            }
            delete modal?.dataset.procedureProcessing;
            return;
        }

        if (modal.dataset.procedureAutoFilled === 'true' || modal.dataset.procedureProcessing === 'true') {
            return;
        }

        const selectLoaiGiay = modal.querySelector('select[name="data[LOAIGIAYCK]"], select[id$="-LOAIGIAYCK"]');
        if (!selectLoaiGiay) return;

        modal.dataset.procedureProcessing = 'true';

        try {
            // [CẬP NHẬT 1]: Chờ đúng 1 giây sau khi mở modal để Form.io & Choices.js render hoàn tất DOM
            await new Promise(resolve => setTimeout(resolve, 1000));

            // [CẬP NHẬT 2]: Thử chọn Loại giấy cam đoan lần 1
            let loaiGiaySuccess = await selectChoiceByText(modal, 'LOAIGIAYCK', CONFIG.procedure.emergencySearchText);

            // Bác sĩ phẫu thuật: Phan Đình Huy
            await selectChoiceByText(modal, 'BACSIPT', CONFIG.procedure.doctorSearchText);

            // Chẩn đoán & Mã ICD (3 lựa chọn ưu tiên)
            const matchedIcd = getFirstAvailableValue(CONFIG.procedure.prioritySources.icd);
            const matchedChanDoan = getFirstAvailableValue(CONFIG.procedure.prioritySources.chandoan);

            if (matchedIcd) {
                const icdInput = modal.querySelector('[name="data[ICD_CHANDOAN]"], input[id$="-ICD_CHANDOAN"]');
                setFieldValue(icdInput, matchedIcd);
            }

            if (matchedChanDoan) {
                const chanDoanInput = modal.querySelector('[name="data[TENICD_CHANDOAN]"], input[id$="-TENICD_CHANDOAN"]');
                setFieldValue(chanDoanInput, matchedChanDoan);
            }

            // Ghép chuỗi vào textarea data[CHANDOAN]: "ICD - Tên bệnh"
            const fullDiagnosisTextarea = modal.querySelector('textarea[name="data[CHANDOAN]"], textarea[id$="-CHANDOAN"]');
            if (fullDiagnosisTextarea) {
                let combinedText = '';
                if (matchedIcd && matchedChanDoan) {
                    combinedText = `${matchedIcd} - ${matchedChanDoan}`;
                } else {
                    combinedText = matchedIcd || matchedChanDoan || '';
                }
                if (combinedText) {
                    setFieldValue(fullDiagnosisTextarea, combinedText);
                }
            }

            // Phương pháp PT, GMHS, Thông tin giải thích & Nguy cơ tai biến
            for (const item of CONFIG.procedure.choicesFieldDefaults) {
                await setChoicesMultipleOrSingle(modal, item.name, item.values, item.textList, item.isMultiple);
            }

            // Đại diện: Thân nhân người bệnh
            await selectChoiceByText(modal, 'DAIDIEN', CONFIG.procedure.representativeSearchText);

            // Điền ngày tạo phiếu qua Flatpickr
            applyCurrentDateToFlatpickr(modal);

            // [CẬP NHẬT 2 - TIẾP TỤC]: Nếu lần 1 chưa chọn được Loại giấy cam đoan, quay lại chọn tiếp lần 2
            if (!loaiGiaySuccess) {
                console.log('[Procedure Form] Thử chọn lại Loại giấy cam đoan lần 2...');
                await new Promise(resolve => setTimeout(resolve, 300));
                loaiGiaySuccess = await selectChoiceByText(modal, 'LOAIGIAYCK', CONFIG.procedure.emergencySearchText);
            }

            modal.dataset.procedureAutoFilled = 'true';
        } catch (err) {
            console.error('[Procedure Form] Lỗi khi điền tự động:', err);
        } finally {
            delete modal.dataset.procedureProcessing;
        }
    }

    // ==========================================
    // THEO DÕI VÀ KÍCH HOẠT
    // ==========================================
    const observer = new MutationObserver(() => {
        handleDoctorSelection();
        handleNutritionForm();
        handleProcedureConsentForm();
    });

    observer.observe(document.body, {
        childList: true,
        subtree: true,
        attributes: true,
        attributeFilter: ['style', 'class']
    });

    handleDoctorSelection();
    handleNutritionForm();
    handleProcedureConsentForm();
})();
